package ru.zhukhly.bank;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.content.*;import java.util.*;
public class SellerGame {
static void open(MainActivity a){new SellerGame(a).open();}
final MainActivity a; final SharedPreferences p; final Random r=new Random(); final Handler h=new Handler(Looper.getMainLooper()); Dialog d; LinearLayout layout; TextView stats,notice; Scene scene; int xp,customers,warranties,services,combo,shop,rebirth; double earnings,turnover; long end; int[] levels=new int[12]; String[] names={"Гарантия","Услуги","Скорость","Харизма","Убеждение","Стрессоустойчивость","Знание техники","Мультиуслуги","VIP-клиенты","Комиссия","Опыт","План"}; String[] goods={"Смартфон","Ноутбук","Телевизор","Холодильник","Пылесос","Монитор"}; int[] prices={35000,75000,60000,55000,18000,24000}; String item="Ожидание клиента"; int product=0; long start;
SellerGame(MainActivity a){this.a=a;p=a.getSharedPreferences("seller",0);xp=p.getInt("xp",0);earnings=Double.longBitsToDouble(p.getLong("earn",0));shop=p.getInt("shop",0);rebirth=p.getInt("rebirth",0);for(int i=0;i<12;i++)levels[i]=p.getInt("l"+i,0);}
void save(){SharedPreferences.Editor e=p.edit().putInt("xp",xp).putLong("earn",Double.doubleToLongBits(earnings)).putInt("shop",shop).putInt("rebirth",rebirth);for(int i=0;i<12;i++)e.putInt("l"+i,levels[i]);e.apply();}
int level(){return 1+xp/100;}
String money(double x){return String.format(Locale.US,"%,.2f ₽",x);}
TextView label(String s,int size){TextView t=new TextView(a);t.setText(s);t.setTextSize(size);t.setTextColor(-1);t.setPadding(12,10,12,10);layout.addView(t);return t;}
void button(String s,Runnable run){Button b=new Button(a);b.setText(s);b.setTextColor(-1);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffb84b12));layout.addView(b);b.setOnClickListener(v->run.run());}
void refresh(){stats.setText("Уровень "+level()+" · Опыт "+xp+"\nКасса смены: "+money(earnings)+"\nБанк: "+money(a.balance)+"\nКлиенты "+customers+" · Гарантии "+warranties+" · Услуги "+services);}
void open(){d=new Dialog(a,android.R.style.Theme_Material_NoActionBar);ScrollView scroll=new ScrollView(a);layout=new LinearLayout(a);layout.setOrientation(1);layout.setPadding(20,20,20,20);layout.setBackgroundColor(0xff171717);scroll.addView(layout);d.setContentView(scroll);label("ЖУХЛЫЙ ПРОДАВЕЦ",25).setTextColor(0xffff9b35);label("Легенда DNS · виртуальная игра",15);stats=label("",16);scene=new Scene();layout.addView(scene,new LinearLayout.LayoutParams(-1,(int)(220*a.getResources().getDisplayMetrics().density)));notice=label("Начни смену",18);button("Начать смену · 10 минут",()->{if(end>SystemClock.elapsedRealtime())return;customers=warranties=services=combo=0;turnover=0;end=SystemClock.elapsedRealtime()+600000;tick();});button("Забрать заработок",()->{if(earnings<=0)return;a.balance+=earnings;a.history.add(0,"Жухлый продавец · зарплата +"+money(earnings));earnings=0;a.save();save();refresh();});button("Прокачка персонажа",()->upgrade());button("Развитие магазина",()->store());button("Перерождение · уровень 100",()->{if(level()<100)return;xp=0;Arrays.fill(levels,0);rebirth++;save();refresh();});button("Назад",()->d.dismiss());d.setOnDismissListener(x->{h.removeCallbacksAndMessages(null);save();});refresh();d.show();}
void upgrade(){String[] opts=new String[12];for(int i=0;i<12;i++)opts[i]=names[i]+" · "+levels[i]+" ур. · "+money(cost(i));new AlertDialog.Builder(a).setTitle("Прокачка").setItems(opts,(x,i)->{double c=cost(i);if(a.balance<c){Toast.makeText(a,"Недостаточно средств",0).show();return;}a.balance-=c;levels[i]++;a.save();save();refresh();upgrade();}).show();}
double cost(int i){return 1000*Math.pow(1.45,levels[i]);}
void store(){int[] costs={100000,250000,500000,1000000,5000000,25000000,100000000};String[] n={"Касса","Продавец","Реклама","Ассортимент","VIP","Второй магазин","Сеть"};if(shop>=costs.length)return;new AlertDialog.Builder(a).setTitle(n[shop]).setMessage(money(costs[shop])).setPositiveButton("Купить",(x,y)->{if(a.balance>=costs[shop]){a.balance-=costs[shop];shop++;a.save();save();refresh();}}).setNegativeButton("Отмена",null).show();}
void tick(){if(!d.isShowing())return;if(SystemClock.elapsedRealtime()>=end){notice.setText("Смена завершена · оборот "+money(turnover));return;}product=r.nextInt(goods.length);item=goods[product];start=SystemClock.elapsedRealtime();scene.invalidate();h.postDelayed(()->{if(!d.isShowing())return;double price=prices[product]*(1+shop*.12+levels[8]*.04);boolean w=r.nextDouble()<Math.min(.95,.25+levels[0]*.025+levels[3]*.01+levels[4]*.01),s=r.nextDouble()<Math.min(.95,.2+levels[1]*.03+levels[6]*.01);double gain=(w?price*.013:0)+(s?200*(1+levels[7]*.1):0);if(w){warranties++;combo++;if(combo%5==0)gain+=500;}else combo=0;if(s)services++;customers++;turnover+=price;xp+=10+levels[10];earnings+=gain*(1+levels[9]*.03+rebirth*.1);notice.setText(item+" · "+(w&&s?"Гарантия + услуга":w?"Гарантия":s?"Услуга":"Отказ")+" · +"+money(gain));notice.setTextColor(w&&s?0xffce93ff:w?0xff65e88b:s?0xffffd54f:0xffff7777);notice.setAlpha(.2f);notice.animate().alpha(1).setDuration(400).start();save();refresh();h.postDelayed(()->tick(),Math.max(300,1800-levels[2]*80));},1600);}
class Scene extends View{Paint b=new Paint(3);Scene(){super(a);}void rect(Canvas c,int color,float x,float y,float w,float h){b.setColor(color);c.drawRoundRect(x,y,x+w,y+h,6,6,b);}void person(Canvas c,float x,float y,int color){b.setColor(0xffefb98a);c.drawCircle(x,y,13,b);rect(c,color,x-17,y+15,34,43);rect(c,0xff343842,x-15,y+58,12,28);rect(c,0xff343842,x+3,y+58,12,28);}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/340f,getHeight()/220f);c.drawColor(0xff28282b);rect(c,0xffef7900,0,0,340,30);b.setColor(-1);b.setTextSize(18);c.drawText("DNS  •  МАГАЗИН ТЕХНИКИ",12,21,b);for(int i=0;i<4;i++){rect(c,0xff55565a,10+i*82,42,72,46);rect(c,0xff182f42,20+i*82,48,52,27);}person(c,245,103,0xfff58220);b.setColor(-1);b.setTextSize(10);c.drawText("Вадим Жухлый · "+level(),200,83,b);float t=Math.min(1,(SystemClock.elapsedRealtime()-start)/1600f);if(start>0){person(c,35+135*t,112,0xff487da0);rect(c,0xffa4b7c8,49+135*t,150,25,20);}rect(c,0xffad561c,205,177,130,35);c.restore();if(start>0&&t<1)postInvalidateDelayed(16);}}
}
